111	// In the Driver::MainLoop, we change the terminal settings.  This function is
112	// added as an atexit handler to make sure we clean them up.
113	static void reset_stdin_termios() {
114	  if (g_old_stdin_termios_is_valid) {
115	    g_old_stdin_termios_is_valid = false;
116	    ::tcsetattr(STDIN_FILENO, TCSANOW, &g_old_stdin_termios);
