132	
133	void Driver::OptionData::AddInitialCommand(std::string command,
134	                                           CommandPlacement placement,
135	                                           bool is_file, SBError &error) {
136	  std::vector<InitialCmdEntry> *command_set;
137	  switch (placement) {
138	  case eCommandPlacementBeforeFile:
139	    command_set = &(m_initial_commands);
140	    break;
141	  case eCommandPlacementAfterFile:
142	    command_set = &(m_after_file_commands);
143	    break;
144	  case eCommandPlacementAfterCrash:
145	    command_set = &(m_after_crash_commands);
146	    break;
147	  }
148	
149	  if (is_file) {
150	    SBFileSpec file(command.c_str());
151	    if (file.Exists())
152	      command_set->push_back(InitialCmdEntry(command, is_file));
153	    else if (file.ResolveExecutableLocation()) {
154	      char final_path[PATH_MAX];
155	      file.GetPath(final_path, sizeof(final_path));
156	      command_set->push_back(InitialCmdEntry(final_path, is_file));
157	    } else
158	      error.SetErrorStringWithFormat(
159	          "file specified in --source (-s) option doesn't exist: '%s'",
160	          command.c_str());
161	  } else
162	    command_set->push_back(InitialCmdEntry(command, is_file));
163	}
164	
165	void Driver::WriteCommandsForSourcing(CommandPlacement placement,
166	                                      SBStream &strm) {
167	  std::vector<OptionData::InitialCmdEntry> *command_set;
168	  switch (placement) {
169	  case eCommandPlacementBeforeFile:
170	    command_set = &m_option_data.m_initial_commands;
171	    break;
172	  case eCommandPlacementAfterFile:
173	    command_set = &m_option_data.m_after_file_commands;
174	    break;
175	  case eCommandPlacementAfterCrash:
176	    command_set = &m_option_data.m_after_crash_commands;
177	    break;
178	  }
179	
180	  for (const auto &command_entry : *command_set) {
181	    const char *command = command_entry.contents.c_str();
182	    if (command_entry.is_file) {
183	      bool source_quietly =
184	          m_option_data.m_source_quietly || command_entry.source_quietly;
185	      strm.Printf("command source -s %i '%s'\n",
186	                  static_cast<int>(source_quietly), command);
187	    } else
188	      strm.Printf("%s\n", command);
189	  }
190	}
191	
192	// Check the arguments that were passed to this program to make sure they are
193	// valid and to get their argument values (if any).  Return a boolean value
194	// indicating whether or not to start up the full debugger (i.e. the Command
195	// Interpreter) or not.  Return FALSE if the arguments were invalid OR if the
196	// user only wanted help or version information.
197	SBError Driver::ProcessArgs(const opt::InputArgList &args, bool &exiting) {
198	  SBError error;
199	
200	  // This is kind of a pain, but since we make the debugger in the Driver's
201	  // constructor, we can't know at that point whether we should read in init
202	  // files yet.  So we don't read them in in the Driver constructor, then set
203	  // the flags back to "read them in" here, and then if we see the "-n" flag,
204	  // we'll turn it off again.  Finally we have to read them in by hand later in
205	  // the main loop.
206	  m_debugger.SkipLLDBInitFiles(false);
207	  m_debugger.SkipAppInitFiles(false);
208	
209	  if (args.hasArg(OPT_no_use_colors)) {
210	    m_debugger.SetUseColor(false);
211	    WithColor::setAutoDetectFunction(disable_color);
212	  }
213	
214	  if (args.hasArg(OPT_version)) {
215	    m_option_data.m_print_version = true;
216	  }
217	
218	  if (args.hasArg(OPT_python_path)) {
219	    m_option_data.m_print_python_path = true;
220	  }
221	  if (args.hasArg(OPT_print_script_interpreter_info)) {
222	    m_option_data.m_print_script_interpreter_info = true;
223	  }
224	
225	  if (args.hasArg(OPT_batch)) {
226	    m_option_data.m_batch = true;
227	  }
228	
229	  if (auto *arg = args.getLastArg(OPT_core)) {
230	    auto *arg_value = arg->getValue();
231	    SBFileSpec file(arg_value);
232	    if (!file.Exists()) {
233	      error.SetErrorStringWithFormat(
234	          "file specified in --core (-c) option doesn't exist: '%s'",
235	          arg_value);
236	      return error;
237	    }
238	    m_option_data.m_core_file = arg_value;
239	  }
240	
241	  if (args.hasArg(OPT_editor)) {
242	    m_option_data.m_use_external_editor = true;
243	  }
244	
245	  if (args.hasArg(OPT_no_lldbinit)) {
246	    m_debugger.SkipLLDBInitFiles(true);
247	    m_debugger.SkipAppInitFiles(true);
248	  }
249	
250	  if (args.hasArg(OPT_local_lldbinit)) {
251	    lldb::SBDebugger::SetInternalVariable("target.load-cwd-lldbinit", "true",
252	                                          m_debugger.GetInstanceName());
253	  }
254	
255	  if (auto *arg = args.getLastArg(OPT_file)) {
256	    auto *arg_value = arg->getValue();
257	    SBFileSpec file(arg_value);
258	    if (file.Exists()) {
259	      m_option_data.m_args.emplace_back(arg_value);
260	    } else if (file.ResolveExecutableLocation()) {
261	      char path[PATH_MAX];
262	      file.GetPath(path, sizeof(path));
263	      m_option_data.m_args.emplace_back(path);
264	    } else {
265	      error.SetErrorStringWithFormat(
266	          "file specified in --file (-f) option doesn't exist: '%s'",
267	          arg_value);
268	      return error;
269	    }
270	  }
271	
272	  if (auto *arg = args.getLastArg(OPT_arch)) {
273	    auto *arg_value = arg->getValue();
274	    if (!lldb::SBDebugger::SetDefaultArchitecture(arg_value)) {
275	      error.SetErrorStringWithFormat(
276	          "invalid architecture in the -a or --arch option: '%s'", arg_value);
277	      return error;
278	    }
279	  }
280	
281	  if (auto *arg = args.getLastArg(OPT_script_language)) {
282	    auto *arg_value = arg->getValue();
283	    m_debugger.SetScriptLanguage(m_debugger.GetScriptingLanguage(arg_value));
284	  }
285	
286	  if (args.hasArg(OPT_source_quietly)) {
287	    m_option_data.m_source_quietly = true;
288	  }
289	
290	  if (auto *arg = args.getLastArg(OPT_attach_name)) {
291	    auto *arg_value = arg->getValue();
292	    m_option_data.m_process_name = arg_value;
293	  }
294	
295	  if (args.hasArg(OPT_wait_for)) {
296	    if (!args.hasArg(OPT_attach_name)) {
297	      error.SetErrorStringWithFormat(
298	          "--wait-for requires a name (--attach-name)");
299	      return error;
300	    }
301	
302	    m_option_data.m_wait_for = true;
303	  }
304	
305	  if (auto *arg = args.getLastArg(OPT_attach_pid)) {
306	    auto *arg_value = arg->getValue();
307	    char *remainder;
308	    m_option_data.m_process_pid = strtol(arg_value, &remainder, 0);
309	    if (remainder == arg_value || *remainder != '\0') {
310	      error.SetErrorStringWithFormat(
311	          "Could not convert process PID: \"%s\" into a pid.", arg_value);
312	      return error;
313	    }
314	  }
315	
316	  if (auto *arg = args.getLastArg(OPT_repl_language)) {
317	    auto *arg_value = arg->getValue();
318	    m_option_data.m_repl_lang =
319	        SBLanguageRuntime::GetLanguageTypeFromString(arg_value);
320	    if (m_option_data.m_repl_lang == eLanguageTypeUnknown) {
321	      error.SetErrorStringWithFormat("Unrecognized language name: \"%s\"",
322	                                     arg_value);
323	      return error;
324	    }
325	    m_debugger.SetREPLLanguage(m_option_data.m_repl_lang);
326	  }
327	
328	  if (args.hasArg(OPT_repl)) {
329	    m_option_data.m_repl = true;
330	  }
331	
332	  if (auto *arg = args.getLastArg(OPT_repl_)) {
333	    m_option_data.m_repl = true;
334	    if (auto *arg_value = arg->getValue())
335	      m_option_data.m_repl_options = arg_value;
336	  }
337	
338	  // We need to process the options below together as their relative order
339	  // matters.
340	  for (auto *arg : args.filtered(OPT_source_on_crash, OPT_one_line_on_crash,
341	                                 OPT_source, OPT_source_before_file,
342	                                 OPT_one_line, OPT_one_line_before_file)) {
343	    auto *arg_value = arg->getValue();
344	    if (arg->getOption().matches(OPT_source_on_crash)) {
345	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementAfterCrash,
346	                                      true, error);
347	      if (error.Fail())
348	        return error;
349	    }
350	
351	    if (arg->getOption().matches(OPT_one_line_on_crash)) {
352	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementAfterCrash,
353	                                      false, error);
354	      if (error.Fail())
355	        return error;
356	    }
357	
358	    if (arg->getOption().matches(OPT_source)) {
359	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementAfterFile,
360	                                      true, error);
361	      if (error.Fail())
362	        return error;
363	    }
364	
365	    if (arg->getOption().matches(OPT_source_before_file)) {
366	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementBeforeFile,
367	                                      true, error);
368	      if (error.Fail())
369	        return error;
370	    }
371	
372	    if (arg->getOption().matches(OPT_one_line)) {
373	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementAfterFile,
374	                                      false, error);
375	      if (error.Fail())
376	        return error;
377	    }
378	
379	    if (arg->getOption().matches(OPT_one_line_before_file)) {
380	      m_option_data.AddInitialCommand(arg_value, eCommandPlacementBeforeFile,
381	                                      false, error);
382	      if (error.Fail())
383	        return error;
384	    }
385	  }
386	
387	  if (m_option_data.m_process_name.empty() &&
388	      m_option_data.m_process_pid == LLDB_INVALID_PROCESS_ID) {
389	
390	    for (auto *arg : args.filtered(OPT_INPUT))
391	      m_option_data.m_args.push_back(arg->getAsString((args)));
392	
393	    // Any argument following -- is an argument for the inferior.
394	    if (auto *arg = args.getLastArgNoClaim(OPT_REM)) {
395	      for (auto *value : arg->getValues())
396	        m_option_data.m_args.emplace_back(value);
397	    }
398	  } else if (args.getLastArgNoClaim() != nullptr) {
399	    WithColor::warning() << "program arguments are ignored when attaching.\n";
400	  }
401	
402	  if (m_option_data.m_print_version) {
403	    llvm::outs() << lldb::SBDebugger::GetVersionString() << '\n';
404	    exiting = true;
405	    return error;
406	  }
407	
408	  if (m_option_data.m_print_python_path) {
409	    SBFileSpec python_file_spec =
410	        SBHostOS::GetScriptPath(lldb::eScriptLanguagePython);
411	    if (python_file_spec.IsValid()) {
412	      char python_path[PATH_MAX];
413	      size_t num_chars = python_file_spec.GetPath(python_path, PATH_MAX);
414	      if (num_chars < PATH_MAX) {
415	        llvm::outs() << python_path << '\n';
416	      } else
417	        llvm::outs() << "<PATH TOO LONG>\n";
418	    } else
419	      llvm::outs() << "<COULD NOT FIND PATH>\n";
420	    exiting = true;
421	    return error;
422	  }
423	
424	  if (m_option_data.m_print_script_interpreter_info) {
425	    SBStructuredData info =
426	        m_debugger.GetScriptInterpreterInfo(m_debugger.GetScriptLanguage());
427	    if (!info) {
428	      error.SetErrorString("no script interpreter.");
429	    } else {
430	      SBStream stream;
431	      error = info.GetAsJSON(stream);
432	      if (error.Success()) {
433	        llvm::outs() << stream.GetData() << '\n';
434	      }
435	    }
436	    exiting = true;
437	    return error;
438	  }
439	
440	  return error;
441	}
