443	std::string EscapeString(std::string arg) {
444	  std::string::size_type pos = 0;
445	  while ((pos = arg.find_first_of("\"\\", pos)) != std::string::npos) {
446	    arg.insert(pos, 1, '\\');
447	    pos += 2;
448	  }
449	  return '"' + arg + '"';
450	}
