452	int Driver::MainLoop() {
453	  if (::tcgetattr(STDIN_FILENO, &g_old_stdin_termios) == 0) {
454	    g_old_stdin_termios_is_valid = true;
455	    atexit(reset_stdin_termios);
456	  }
457	
458	  ::setbuf(stdin, nullptr);
459	  ::setbuf(stdout, nullptr);
460	
461	  m_debugger.SetErrorFileHandle(stderr, false);
462	  m_debugger.SetOutputFileHandle(stdout, false);
463	  // Don't take ownership of STDIN yet...
464	  m_debugger.SetInputFileHandle(stdin, false);
465	
466	  m_debugger.SetUseExternalEditor(m_option_data.m_use_external_editor);
467	  m_debugger.SetShowInlineDiagnostics(true);
468	
469	  // Set the terminal dimensions.
470	  UpdateWindowSize();
471	
472	  SBCommandInterpreter sb_interpreter = m_debugger.GetCommandInterpreter();
473	
474	  // Process lldbinit files before handling any options from the command line.
475	  SBCommandReturnObject result;
476	  sb_interpreter.SourceInitFileInGlobalDirectory(result);
477	  sb_interpreter.SourceInitFileInHomeDirectory(result, m_option_data.m_repl);
478	
479	  // Source the local .lldbinit file if it exists and we're allowed to source.
480	  // Here we want to always print the return object because it contains the
481	  // warning and instructions to load local lldbinit files.
482	  sb_interpreter.SourceInitFileInCurrentWorkingDirectory(result);
483	  result.PutError(m_debugger.GetErrorFile());
484	  result.PutOutput(m_debugger.GetOutputFile());
485	
486	  // We allow the user to specify an exit code when calling quit which we will
487	  // return when exiting.
488	  m_debugger.GetCommandInterpreter().AllowExitCodeOnQuit(true);
489	
490	  // Now we handle options we got from the command line
491	  SBStream commands_stream;
492	
493	  // First source in the commands specified to be run before the file arguments
494	  // are processed.
495	  WriteCommandsForSourcing(eCommandPlacementBeforeFile, commands_stream);
496	
497	  // If we're not in --repl mode, add the commands to process the file
498	  // arguments, and the commands specified to run afterwards.
499	  if (!m_option_data.m_repl) {
500	    const size_t num_args = m_option_data.m_args.size();
501	    if (num_args > 0) {
502	      char arch_name[64];
503	      if (lldb::SBDebugger::GetDefaultArchitecture(arch_name,
504	                                                   sizeof(arch_name)))
505	        commands_stream.Printf("target create --arch=%s %s", arch_name,
506	                               EscapeString(m_option_data.m_args[0]).c_str());
507	      else
508	        commands_stream.Printf("target create %s",
509	                               EscapeString(m_option_data.m_args[0]).c_str());
510	
511	      if (!m_option_data.m_core_file.empty()) {
512	        commands_stream.Printf(" --core %s",
513	                               EscapeString(m_option_data.m_core_file).c_str());
514	      }
515	      commands_stream.Printf("\n");
516	
517	      if (num_args > 1) {
518	        commands_stream.Printf("settings set -- target.run-args ");
519	        for (size_t arg_idx = 1; arg_idx < num_args; ++arg_idx)
520	          commands_stream.Printf(
521	              " %s", EscapeString(m_option_data.m_args[arg_idx]).c_str());
522	        commands_stream.Printf("\n");
523	      }
524	    } else if (!m_option_data.m_core_file.empty()) {
525	      commands_stream.Printf("target create --core %s\n",
526	                             EscapeString(m_option_data.m_core_file).c_str());
527	    } else if (!m_option_data.m_process_name.empty()) {
528	      commands_stream.Printf(
529	          "process attach --name %s",
530	          EscapeString(m_option_data.m_process_name).c_str());
531	
532	      if (m_option_data.m_wait_for)
533	        commands_stream.Printf(" --waitfor");
534	
535	      commands_stream.Printf("\n");
536	
537	    } else if (LLDB_INVALID_PROCESS_ID != m_option_data.m_process_pid) {
538	      commands_stream.Printf("process attach --pid %" PRIu64 "\n",
539	                             m_option_data.m_process_pid);
540	    }
541	
542	    WriteCommandsForSourcing(eCommandPlacementAfterFile, commands_stream);
543	  } else if (!m_option_data.m_after_file_commands.empty()) {
544	    // We're in repl mode and after-file-load commands were specified.
545	    WithColor::warning() << "commands specified to run after file load (via -o "
546	                            "or -s) are ignored in REPL mode.\n";
547	  }
548	
549	  const bool handle_events = true;
550	  const bool spawn_thread = false;
551	
552	  // Check if we have any data in the commands stream, and if so, save it to a
553	  // temp file
554	  // so we can then run the command interpreter using the file contents.
555	  bool go_interactive = !m_option_data.m_batch;
556	  if ((commands_stream.GetData() != nullptr) &&
557	      (commands_stream.GetSize() != 0u)) {
558	    SBError error = m_debugger.SetInputString(commands_stream.GetData());
559	    if (error.Fail()) {
560	      WithColor::error() << error.GetCString() << '\n';
561	      return 1;
562	    }
563	
564	    // Set the debugger into Sync mode when running the command file. Otherwise
565	    // command files that run the target won't run in a sensible way.
566	    bool old_async = m_debugger.GetAsync();
567	    m_debugger.SetAsync(false);
568	
569	    SBCommandInterpreterRunOptions options;
570	    options.SetAutoHandleEvents(true);
571	    options.SetSpawnThread(false);
572	    options.SetStopOnError(true);
573	    options.SetStopOnCrash(m_option_data.m_batch);
574	    options.SetEchoCommands(!m_option_data.m_source_quietly);
575	
576	    SBCommandInterpreterRunResult results =
577	        m_debugger.RunCommandInterpreter(options);
578	    if (results.GetResult() == lldb::eCommandInterpreterResultQuitRequested)
579	      go_interactive = false;
580	    if (m_option_data.m_batch &&
581	        results.GetResult() != lldb::eCommandInterpreterResultInferiorCrash)
582	      go_interactive = false;
583	
584	    // When running in batch mode and stopped because of an error, exit with a
585	    // non-zero exit status.
586	    if (m_option_data.m_batch &&
587	        results.GetResult() == lldb::eCommandInterpreterResultCommandError)
588	      return 1;
589	
590	    if (m_option_data.m_batch &&
591	        results.GetResult() == lldb::eCommandInterpreterResultInferiorCrash &&
592	        !m_option_data.m_after_crash_commands.empty()) {
593	      go_interactive = true;
594	      SBStream crash_commands_stream;
595	      WriteCommandsForSourcing(eCommandPlacementAfterCrash,
596	                               crash_commands_stream);
597	      SBError error =
598	          m_debugger.SetInputString(crash_commands_stream.GetData());
599	      if (error.Success()) {
600	        SBCommandInterpreterRunResult local_results =
601	            m_debugger.RunCommandInterpreter(options);
602	        if (local_results.GetResult() ==
603	            lldb::eCommandInterpreterResultQuitRequested)
604	          go_interactive = false;
605	
606	        // When running in batch mode and an error occurred while sourcing
607	        // the crash commands, exit with a non-zero exit status.
608	        if (m_option_data.m_batch &&
609	            local_results.GetResult() ==
610	                lldb::eCommandInterpreterResultCommandError)
611	          return 1;
612	      }
613	    }
614	    m_debugger.SetAsync(old_async);
615	  }
616	
617	  // Now set the input file handle to STDIN and run the command interpreter
618	  // again in interactive mode or repl mode and let the debugger take ownership
619	  // of stdin.
620	  if (go_interactive) {
621	    m_debugger.SetInputFileHandle(stdin, true);
622	
623	    if (m_option_data.m_repl) {
624	      const char *repl_options = nullptr;
625	      if (!m_option_data.m_repl_options.empty())
626	        repl_options = m_option_data.m_repl_options.c_str();
627	      SBError error(
628	          m_debugger.RunREPL(m_option_data.m_repl_lang, repl_options));
629	      if (error.Fail()) {
630	        const char *error_cstr = error.GetCString();
631	        if ((error_cstr != nullptr) && (error_cstr[0] != 0))
632	          WithColor::error() << error_cstr << '\n';
633	        else
634	          WithColor::error() << error.GetError() << '\n';
635	      }
636	    } else {
637	      m_debugger.RunCommandInterpreter(handle_events, spawn_thread);
638	    }
639	  }
640	
641	  reset_stdin_termios();
642	  fclose(stdin);
643	
644	  return sb_interpreter.GetQuitStatus();
645	}
