647	void Driver::UpdateWindowSize() {
648	  struct winsize window_size;
649	  if ((isatty(STDIN_FILENO) != 0) &&
650	      ::ioctl(STDIN_FILENO, TIOCGWINSZ, &window_size) == 0) {
651	    if (window_size.ws_col > 0) {
652	      // Set both dimensions together to avoid recomputing from a stale value.
653	#ifndef _WIN32
654	      m_debugger.SetTerminalDimensions(window_size.ws_col, window_size.ws_row);
655	#else
656	      m_debugger.SetTerminalDimensions(window_size.ws_col,
657	                                       m_debugger.GetTerminalHeight());
658	#endif
659	    }
660	  }
661	}
