664	void sigint_handler(int signo) {
665	  // Restore handler as it is not persistent on Windows.
666	  signal(SIGINT, sigint_handler);
667	
668	  static std::atomic_flag g_interrupt_sent = ATOMIC_FLAG_INIT;
669	  if (g_driver != nullptr) {
670	    if (!g_interrupt_sent.test_and_set()) {
671	      g_driver->GetDebugger().DispatchInputInterrupt();
672	      g_interrupt_sent.clear();
673	      return;
674	    }
675	  }
676	
677	  _exit(signo);
678	}
