681	static void printHelp(LLDBOptTable &table, llvm::StringRef tool_name) {
682	  std::string usage_str = tool_name.str() + " [options]";
683	  table.printHelp(llvm::outs(), usage_str.c_str(), "LLDB", false);
684	
685	  std::string examples = R"___(
686	EXAMPLES:
687	  The debugger can be started in several modes.
688	
689	  Passing an executable as a positional argument prepares lldb to debug the
690	  given executable. To disambiguate between arguments passed to lldb and
691	  arguments passed to the debugged executable, arguments starting with a - must
692	  be passed after --.
693	
694	    lldb --arch x86_64 /path/to/program program argument -- --arch armv7
695	
696	  For convenience, passing the executable after -- is also supported.
697	
698	    lldb --arch x86_64 -- /path/to/program program argument --arch armv7
699	
700	  Passing one of the attach options causes lldb to immediately attach to the
701	  given process.
702	
703	    lldb -p <pid>
704	    lldb -n <process-name>
705	
706	  Passing --repl starts lldb in REPL mode.
707	
708	    lldb -r
709	
710	  Passing --core causes lldb to debug the core file.
711	
712	    lldb -c /path/to/core
713	
714	  Command options can be combined with these modes and cause lldb to run the
715	  specified commands before or after events, like loading the file or crashing,
716	  in the order provided on the command line.
717	
718	    lldb -O 'settings set stop-disassembly-count 20' -o 'run' -o 'bt'
719	    lldb -S /source/before/file -s /source/after/file
720	    lldb -K /source/before/crash -k /source/after/crash
721	
722	  Note: In REPL mode no file is loaded, so commands specified to run after
723	  loading the file (via -o or -s) will be ignored.)___";
724	  llvm::outs() << examples << '\n';
725	}
