727	int main(int argc, char const *argv[]) {
728	  // Editline uses for example iswprint which is dependent on LC_CTYPE.
729	  std::setlocale(LC_ALL, "");
730	  std::setlocale(LC_CTYPE, "");
731	
732	  // Setup LLVM signal handlers and make sure we call llvm_shutdown() on
733	  // destruction.
734	  llvm::InitLLVM IL(argc, argv, /*InstallPipeSignalExitHandler=*/false);
735	#if !defined(__APPLE__)
736	  llvm::setBugReportMsg("PLEASE submit a bug report to " LLDB_BUG_REPORT_URL
737	                        " and include the crash backtrace.\n");
738	#else
739	  llvm::setBugReportMsg("PLEASE submit a bug report to " LLDB_BUG_REPORT_URL
740	                        " and include the crash report from "
741	                        "~/Library/Logs/DiagnosticReports/.\n");
742	#endif
743	
744	  // Parse arguments.
745	  LLDBOptTable T;
746	  unsigned MissingArgIndex;
747	  unsigned MissingArgCount;
748	  ArrayRef<const char *> arg_arr = ArrayRef(argv + 1, argc - 1);
749	  opt::InputArgList input_args =
750	      T.ParseArgs(arg_arr, MissingArgIndex, MissingArgCount);
751	  llvm::StringRef argv0 = llvm::sys::path::filename(argv[0]);
752	
753	  if (input_args.hasArg(OPT_help)) {
754	    printHelp(T, argv0);
755	    return 0;
756	  }
757	
758	  // Check for missing argument error.
759	  if (MissingArgCount) {
760	    WithColor::error() << "argument to '"
761	                       << input_args.getArgString(MissingArgIndex)
762	                       << "' is missing\n";
763	  }
764	  // Error out on unknown options.
765	  if (input_args.hasArg(OPT_UNKNOWN)) {
766	    for (auto *arg : input_args.filtered(OPT_UNKNOWN)) {
767	      WithColor::error() << "unknown option: " << arg->getSpelling() << '\n';
768	    }
769	  }
770	  if (MissingArgCount || input_args.hasArg(OPT_UNKNOWN)) {
771	    llvm::errs() << "Use '" << argv0
772	                 << " --help' for a complete list of options.\n";
773	    return 1;
774	  }
775	
776	#if defined(_WIN32) && LLDB_ENABLE_PYTHON
777	  // liblldb.dll has direct imports from python3xx.dll (the script interpreter
778	  // plugin is statically linked into liblldb), so the loader needs to find
779	  // python3xx.dll before lldb.exe's delay-load thunk for liblldb fires on the
780	  // first SB call below. The runtime loader is statically linked into lldb.exe
781	  // via lldbHost (it has no LLDB_API export), so this call does not itself
782	  // trigger the liblldb.dll load.
783	  llvm::Expected<lldb_private::ScriptInterpreterRuntimeLoader &> python_loader =
784	      lldb_private::ScriptInterpreterRuntimeLoader::Get(eScriptLanguagePython);
785	  if (!python_loader)
786	    WithColor::warning() << llvm::toString(python_loader.takeError()) << '\n';
787	  else if (llvm::Error err = python_loader->Load())
788	    WithColor::warning() << llvm::toString(std::move(err)) << '\n';
789	#endif
790	
791	  SBError error = SBDebugger::InitializeWithErrorHandling();
792	  if (error.Fail()) {
793	    WithColor::error() << "initialization failed: " << error.GetCString()
794	                       << '\n';
795	    return 1;
796	  }
797	
798	  // Setup LLDB signal handlers once the debugger has been initialized.
799	  SBDebugger::PrintDiagnosticsOnError();
800	
801	#ifdef _WIN32
802	  signal(SIGINT, sigint_handler);
803	#else
804	  signal(SIGPIPE, SIG_IGN);
805	
806	  // Capture the main thread's id so the signal thread can target it.
807	  pthread_t main_thread = pthread_self();
808	
809	  // Set when the signal thread sends itself a SIGINT to wake the main thread.
810	  // The next callback invocation observes this flag and skips the work. A
811	  // plain bool is sufficient because the callback only ever runs on the
812	  // signal thread; it lives outside the lambda because MainLoopPosix copies
813	  // the callback on every dispatch, which would discard in-lambda state.
814	  bool skip_next_sigint = false;
815	
816	  // Handle signals in a MainLoop running on a separate thread.
817	  MainLoop signal_loop;
818	  Status signal_status;
819	
820	  auto sigint_handler = signal_loop.RegisterSignal(
821	      SIGINT,
822	      [&, main_thread](MainLoopBase &) {
823	        // Skip the self-sent wakeup SIGINT queued at the end of the previous
824	        // invocation.
825	        if (std::exchange(skip_next_sigint, false))
826	          return;
827	
828	        // Temporarily restore the default disposition so that a second SIGINT
829	        // delivered while DispatchInputInterrupt is running hard-terminates
830	        // the process. This preserves the "double Ctrl-C to force exit"
831	        // escape hatch users rely on when the debugger is unresponsive.
832	        struct sigaction old_action;
833	        struct sigaction new_action = {};
834	        new_action.sa_handler = SIG_DFL;
835	        sigemptyset(&new_action.sa_mask);
836	
837	        int ret = sigaction(SIGINT, &new_action, &old_action);
838	        UNUSED_IF_ASSERT_DISABLED(ret);
839	        assert(ret == 0 && "sigaction failed");
840	
841	        if (g_driver)
842	          g_driver->GetDebugger().DispatchInputInterrupt();
843	
844	        ret = sigaction(SIGINT, &old_action, nullptr);
845	        UNUSED_IF_ASSERT_DISABLED(ret);
846	        assert(ret == 0 && "sigaction failed");
847	
848	        // Wake the main thread so any blocking syscall (e.g. the Python REPL
849	        // waiting on input or sleeping) returns with EINTR. This lets Python
850	        // observe the pending interrupt queued by DispatchInputInterrupt and
851	        // raise KeyboardInterrupt. Flag the resulting callback invocation so
852	        // it's skipped rather than re-running DispatchInputInterrupt.
853	        skip_next_sigint = true;
854	        pthread_kill(main_thread, SIGINT);
855	      },
856	      signal_status);
857	  assert(sigint_handler && signal_status.Success());
858	
859	  auto sigwinch_handler = signal_loop.RegisterSignal(
860	      SIGWINCH,
861	      [&](MainLoopBase &) {
862	        if (g_driver)
863	          g_driver->UpdateWindowSize();
864	      },
865	      signal_status);
866	  assert(sigwinch_handler && signal_status.Success());
867	
868	  auto sigtstp_handler = signal_loop.RegisterSignal(
869	      SIGTSTP,
870	      [&](MainLoopBase &) {
871	        if (g_driver)
872	          g_driver->GetDebugger().SaveInputTerminalState();
873	
874	        struct sigaction old_action;
875	        struct sigaction new_action = {};
876	        new_action.sa_handler = SIG_DFL;
877	        sigemptyset(&new_action.sa_mask);
878	        sigaddset(&new_action.sa_mask, SIGTSTP);
879	
880	        int ret = sigaction(SIGTSTP, &new_action, &old_action);
881	        UNUSED_IF_ASSERT_DISABLED(ret);
882	        assert(ret == 0 && "sigaction failed");
883	
884	        raise(SIGTSTP);
885	
886	        ret = sigaction(SIGTSTP, &old_action, nullptr);
887	        UNUSED_IF_ASSERT_DISABLED(ret);
888	        assert(ret == 0 && "sigaction failed");
889	
890	        if (g_driver)
891	          g_driver->GetDebugger().RestoreInputTerminalState();
892	      },
893	      signal_status);
894	  assert(sigtstp_handler && signal_status.Success());
895	
896	  std::thread signal_thread([&] { signal_loop.Run(); });
897	#endif
898	
899	  int exit_code = 0;
900	  // Create a scope for driver so that the driver object will destroy itself
901	  // before SBDebugger::Terminate() is called.
902	  {
903	    Driver driver;
904	
905	    bool exiting = false;
906	    SBError error(driver.ProcessArgs(input_args, exiting));
907	    if (error.Fail()) {
908	      exit_code = 1;
909	      if (const char *error_cstr = error.GetCString())
910	        WithColor::error() << error_cstr << '\n';
911	    } else if (!exiting) {
912	      exit_code = driver.MainLoop();
913	    }
914	  }
915	
916	  // When terminating the debugger we have to wait on all the background tasks
917	  // to complete, which can take a while. Print a message when this takes longer
918	  // than 1 second.
919	  {
920	    std::future<void> future =
921	        std::async(std::launch::async, []() { SBDebugger::Terminate(); });
922	
923	    if (future.wait_for(std::chrono::seconds(1)) == std::future_status::timeout)
924	      fprintf(stderr, "Waiting for background tasks to complete...\n");
925	
926	    future.wait();
927	  }
928	
929	#if !defined(_WIN32)
930	  // Try to interrupt the signal thread.  If that succeeds, wait for it to exit.
931	  if (signal_loop.AddPendingCallback(
932	          [](MainLoopBase &loop) { loop.RequestTermination(); }))
933	    signal_thread.join();
934	#endif
935	
936	  return exit_code;
937	}
938

